    /**
     * Tests getting all CardTokenizations.
     *
     * @return    Collection
     */
    public List<CardTokenization> testGetAll() throws Throwable {
    LOGGER.info( "CardTokenizationTest:testGetAll() - Retrieving Collection of CardTokenizations:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all CardTokenization : " );
    List<CardTokenization> collection  = null;

    try {
        // call the static get method on the CardTokenizationService
        collection = service.getAllCardTokenization();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            CardTokenization currEntity  = null;
            Iterator<CardTokenization> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCardTokenizationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

